from __future__ import annotations

import os
from pathlib import Path
from typing import Dict, List

from mitreattack.stix20 import MitreAttackData

from .models import DataSource, Domain, Group, Mitigation, Software, SubTechnique, Tactic, Technique

_RAW_CACHE: Dict[Path, Dict[str, MitreAttackData]] = {}


def _default_stix_dir() -> Path:
    return Path(os.environ.get("ATTACK_DATA_DIR", Path.home() / "attack_data"))


class ATTACKLoader:
    def __init__(self, stix_dir: Path | None = None):
        self.stix_dir = (stix_dir or _default_stix_dir()).expanduser().resolve()
        self._raw: Dict[str, MitreAttackData] = {}
        self._load_all()

    def _load_all(self):
        if self.stix_dir in _RAW_CACHE:
            self._raw = _RAW_CACHE[self.stix_dir]
            return

        for domain_key, filename in [
            ("enterprise", "enterprise-attack.json"),
            ("mobile", "mobile-attack.json"),
            ("ics", "ics-attack.json"),
        ]:
            path = self.stix_dir / filename
            if not path.exists():
                raise FileNotFoundError(
                    f"STIX bundle not found: {path}. "
                    "Run: python scripts/download_attack_data.py "
                    "or set ATTACK_DATA_DIR to a directory containing the bundles."
                )
            self._raw[domain_key] = MitreAttackData(str(path))
        _RAW_CACHE[self.stix_dir] = self._raw

    def get_tactics(self, domain: Domain) -> List[Tactic]:
        src = self._raw[domain.value]
        results = []
        for t in src.get_tactics(remove_revoked_deprecated=True):
            ext = t.get("external_references", [{}])[0]
            results.append(
                Tactic(
                    stix_id=t["id"],
                    attack_id=ext.get("external_id", ""),
                    name=t["name"],
                    description=t.get("description", ""),
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_techniques(self, domain: Domain) -> List[Technique]:
        src = self._raw[domain.value]
        results = []
        for t in src.get_techniques(remove_revoked_deprecated=True):
            if t.get("x_mitre_is_subtechnique"):
                continue
            ext = t.get("external_references", [{}])[0]
            results.append(
                Technique(
                    stix_id=t["id"],
                    attack_id=ext.get("external_id", ""),
                    name=t["name"],
                    description=t.get("description", ""),
                    tactic_ids=[kc["phase_name"] for kc in t.get("kill_chain_phases", [])],
                    platforms=t.get("x_mitre_platforms", []),
                    data_sources=t.get("x_mitre_data_sources", []),
                    mitigations=[],
                    kill_chain=t.get("kill_chain_phases", []),
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_subtechniques(self, domain: Domain) -> List[SubTechnique]:
        src = self._raw[domain.value]
        results = []
        for t in src.get_techniques(remove_revoked_deprecated=True):
            if not t.get("x_mitre_is_subtechnique"):
                continue
            ext = t.get("external_references", [{}])[0]
            attack_id = ext.get("external_id", "")
            parent_id = attack_id.split(".")[0] if "." in attack_id else ""
            results.append(
                SubTechnique(
                    stix_id=t["id"],
                    attack_id=attack_id,
                    name=t["name"],
                    description=t.get("description", ""),
                    parent_id=parent_id,
                    tactic_ids=[kc["phase_name"] for kc in t.get("kill_chain_phases", [])],
                    platforms=t.get("x_mitre_platforms", []),
                    data_sources=t.get("x_mitre_data_sources", []),
                    mitigations=[],
                    kill_chain=t.get("kill_chain_phases", []),
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_groups(self, domain: Domain) -> List[Group]:
        src = self._raw[domain.value]
        results = []
        for g in src.get_groups(remove_revoked_deprecated=True):
            ext = g.get("external_references", [{}])[0]
            techniques = []
            for ref in g.get("object_refs", []):
                if ref.startswith("attack-pattern--"):
                    tech = src.get_object_by_stix_id(ref)
                    if tech:
                        ext_ref = tech.get("external_references", [{}])[0]
                        techniques.append(ext_ref.get("external_id", ""))
            software = []
            for ref in g.get("object_refs", []):
                if ref.startswith("malware--") or ref.startswith("tool--"):
                    sw = src.get_object_by_stix_id(ref)
                    if sw:
                        ext_ref = sw.get("external_references", [{}])[0]
                        software.append(ext_ref.get("external_id", ""))
            results.append(
                Group(
                    stix_id=g["id"],
                    attack_id=ext.get("external_id", ""),
                    name=g["name"],
                    aliases=g.get("aliases", []),
                    description=g.get("description", ""),
                    techniques=techniques,
                    software=software,
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_software(self, domain: Domain) -> List[Software]:
        src = self._raw[domain.value]
        results = []
        for s in src.get_software(remove_revoked_deprecated=True):
            ext = s.get("external_references", [{}])[0]
            techniques = []
            for ref in s.get("object_refs", []):
                if ref.startswith("attack-pattern--"):
                    tech = src.get_object_by_stix_id(ref)
                    if tech:
                        ext_ref = tech.get("external_references", [{}])[0]
                        techniques.append(ext_ref.get("external_id", ""))
            results.append(
                Software(
                    stix_id=s["id"],
                    attack_id=ext.get("external_id", ""),
                    name=s["name"],
                    software_type=s.get("x_mitre_type", "malware"),
                    platforms=s.get("x_mitre_platforms", []),
                    techniques=techniques,
                    description=s.get("description", ""),
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_mitigations(self, domain: Domain) -> List[Mitigation]:
        src = self._raw[domain.value]
        results = []
        for m in src.get_mitigations(remove_revoked_deprecated=True):
            ext = m.get("external_references", [{}])[0]
            techniques = []
            for ref in m.get("object_refs", []):
                if ref.startswith("attack-pattern--"):
                    tech = src.get_object_by_stix_id(ref)
                    if tech:
                        ext_ref = tech.get("external_references", [{}])[0]
                        techniques.append(ext_ref.get("external_id", ""))
            results.append(
                Mitigation(
                    stix_id=m["id"],
                    attack_id=ext.get("external_id", ""),
                    name=m["name"],
                    description=m.get("description", ""),
                    techniques=techniques,
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results

    def get_data_sources(self, domain: Domain) -> List[DataSource]:
        src = self._raw[domain.value]
        results = []
        for component in src.get_objects_by_type("x-mitre-data-component"):
            if component.get("revoked") or component.get("x_mitre_deprecated"):
                continue
            domains = component.get("x_mitre_domains", [])
            if f"{domain.value}-attack" not in domains:
                continue
            ext = component.get("external_references", [{}])[0]
            log_sources = component.get("x_mitre_log_sources", [])
            components = [source.get("name", "") for source in log_sources if source.get("name")]
            results.append(
                DataSource(
                    stix_id=component["id"],
                    attack_id=ext.get("external_id", ""),
                    name=component["name"],
                    description=component.get("description", ""),
                    components=components,
                    techniques=[],
                    domain=domain,
                    url=ext.get("url"),
                )
            )
        return results
